using Path=std::filesystem::path;
namespace progress=recovery::v2::progress;
namespace {
constexpr std::uint64_t Generation=94;
struct Ledgers {progress::WorkLedger preparation{recovery::v2::WorkerKind::CancelableHelperPrefix,32},resume{recovery::v2::WorkerKind::DurablePrefix,32};reader::lifecycle::Tracking prep(){return {&preparation,Generation,recovery::v2::WorkerKind::CancelableHelperPrefix};}reader::lifecycle::Tracking saved(){return {&resume,Generation,recovery::v2::WorkerKind::DurablePrefix};}};
progress::Snapshot snapshot(progress::WorkLedger& ledger){auto s=ledger.snapshot();CHECK(s.fault==progress::Fault::None&&s.health.accepted>=s.health.completed&&s.health.backlog==s.health.accepted-s.health.completed);if(s.health.backlog)CHECK(s.health.oldest.generation==Generation&&s.health.oldest.monotonic>0&&s.health.oldest.boottime>0);else CHECK(s.health.oldest==recovery::v2::ClockPair{});return s;}
QString quote(const Path& p){auto s=QString::fromStdString(p.string());s.replace("'","'\\''");return "'"+s+"'";}
// Only the synthetic staged wrapper is changed. It refuses --serve, so the reader uses one-shot helpers (the per-page
// semantics proved here; the page server has its own tests). Its builtin FIFO read creates
// no sleep child; normal release execs the real retained preparation helper.
struct Gate {
 Path directory;
 Gate(const Path& app,const Path& sys):directory(app/"test-helper-gate"){underlay::privateDirectory(directory);auto script=QString("#!/bin/sh\nif [ \"$1\" = --serve ]; then exit 0; fi\nif [ \"$1\" = --page ]; then\n printf '%s\\n' \"$$\" > %1/seen-\"$3\"\n if [ -r %1/target ]; then\n  IFS= read -r target < %1/target\n  if [ \"$3\" = \"$target\" ] && [ -p %1/gate ]; then\n   IFS= read -r released < %1/gate || exit 79\n  fi\n fi\nfi\nexec %2 --library-path %3 %4 \"$@\"\n").arg(quote(directory),quote(sys/"usr/lib/ld-linux-aarch64.so.1"),quote(sys/"usr/lib"),quote(app/"bin/helper-real"));underlay::atomicFile(app/"bin/reader-experience1-prepare",script.toUtf8());CHECK(chmod((app/"bin/reader-experience1-prepare").c_str(),0700)==0);}
 void arm(int page){std::filesystem::remove(directory/"gate");for(int n=0;n<3;++n)std::filesystem::remove(directory/("seen-"+std::to_string(n)));underlay::atomicFile(directory/"target",QByteArray::number(page)+"\n");CHECK(mkfifo((directory/"gate").c_str(),0600)==0);}
 bool seen(int page)const{return std::filesystem::exists(directory/("seen-"+std::to_string(page)));}
 void release(){int fd=-1;until([&]{fd=open((directory/"gate").c_str(),O_WRONLY|O_NONBLOCK|O_CLOEXEC);if(fd<0)CHECK(errno==ENXIO||errno==EINTR);return fd>=0;});CHECK(write(fd,"go\n",3)==3);CHECK(close(fd)==0);CHECK(std::filesystem::remove(directory/"gate"));}
 void clear(){std::filesystem::remove(directory/"gate");std::filesystem::remove(directory/"target");}
};
library::Document importBook(const Path& app,const Path& source,const Path& root){underlay::privateDirectory(root/"inbox");std::filesystem::copy_file(source/"fixtures/library/authored-three-pages.pdf",root/"inbox/authored.pdf");std::atomic<bool> stop{false};reader::syncLibrary(app,root,stop);auto books=library::documents(root);CHECK(books.size()==1&&books[0].pages==3);return books[0];}
underlay::Prepared prepared(const Path& app,const Path& document,int page){std::atomic<bool> stop{false};return reader::prepareViewPage(app,document,page,stop,{});}
void initialFence(reader::Reader& r,Ledgers& ledgers,const Path& document,int page){until([&]{auto s=snapshot(ledgers.resume);return s.health.accepted==1&&s.health.completed==1;});CHECK(!r.failed()&&snapshot(ledgers.preparation).health.accepted==0);auto fence=reader::readViewResume(document,3,{});CHECK(fence.page==page&&!fence.clean&&fence.generation>0);}
void drain(reader::Reader& r,Ledgers& ledgers,const Path& document,int page,std::uint64_t helperJobs,std::uint64_t resumeJobs){r.beginQuiesce();until([&]{return r.pollQuiesce(true,true);});CHECK(r.drained()&&r.shutdownSaved()&&!r.failed());auto h=snapshot(ledgers.preparation),s=snapshot(ledgers.resume);CHECK(h.health.accepted==helperJobs&&h.health.completed==helperJobs&&!h.health.backlog);CHECK(s.health.accepted==resumeJobs&&s.health.completed==resumeJobs&&!s.health.backlog);auto fence=reader::readViewResume(document,3,{});CHECK(fence.page==page&&fence.clean);auto bytes=underlay::readBounded(document/"resume.json",4096);for(unsigned n=0;n<24;++n){CHECK(r.pollQuiesce(true,true)&&r.finish(0)&&r.shutdownSaved());CHECK(snapshot(ledgers.preparation).health==h.health&&snapshot(ledgers.resume).health==s.health&&underlay::readBounded(document/"resume.json",4096)==bytes);}}
}
int main(int argc,char** argv){QCoreApplication application(argc,argv);if(argc!=5)return 64;try{Path source=argv[1],parent=argv[2],build=argv[3],sys=argv[4];underlay::privateDirectory(parent);QTemporaryDir owned(QString::fromStdString((parent/"reader-progress-XXXXXX").string()));CHECK(owned.isValid());owned.setAutoRemove(false);Path data=owned.path().toStdString();std::cout<<"READER_PROGRESS_DATA "<<data<<'\n'<<std::flush;auto app=stage(source,data/"stage",build,sys);Gate gate(app,sys);unsigned cases=0;
 {
  auto root=data/"shell-initial-open";auto book=importBook(app,source,root);auto document=library::documentRoot(root,book.id);gate.arm(0);Ledgers ledgers;ux::Shell shell(app,root,true,false,false,{},{},{},ledgers.prep(),ledgers.saved());Canvas canvas(shell);CHECK(shell.choose(0));auto accepted=snapshot(ledgers.preparation);CHECK(accepted.health.accepted==1&&accepted.health.completed==0&&accepted.health.backlog==1);until([&]{shell.tick();canvas.changes();CHECK(!shell.failed());return gate.seen(0);});for(unsigned n=0;n<32;++n){shell.tick();canvas.changes();CHECK(snapshot(ledgers.preparation).health==accepted.health&&snapshot(ledgers.resume).health.accepted==0&&!shell.document());}gate.release();canvas.ready();until([&]{shell.tick();canvas.changes();CHECK(!shell.failed());auto h=snapshot(ledgers.preparation),s=snapshot(ledgers.resume);return h.health.accepted==2&&h.health.completed==2&&s.health.accepted==1&&s.health.completed==1&&shell.writable();});CHECK(shell.page()==0&&!reader::readViewResume(document,3,{}).clean);CHECK(shell.finish(5000)&&shell.unsaved()==0);auto h=snapshot(ledgers.preparation),s=snapshot(ledgers.resume);CHECK(h.health.accepted==2&&h.health.completed==2&&s.health.accepted==2&&s.health.completed==2&&reader::readViewResume(document,3,{}).clean);for(unsigned n=0;n<16;++n){auto state=shell.pollQuiesce();CHECK(state.drained&&state.saved&&!state.failed);CHECK(snapshot(ledgers.preparation).health==h.health&&snapshot(ledgers.resume).health==s.health);}++cases;std::cout<<"PASS actual_shell_initial_opener_latched real_helper_reaped_main_joined initial_and_final_resume\n"<<std::flush;
 }
 gate.clear();
 {
  auto root=data/"uninstalled-prefetch";auto book=importBook(app,source,root);auto document=library::documentRoot(root,book.id);auto p=prepared(app,document,0);Ledgers ledgers;reader::Reader r(app,document,std::move(p),{},ledgers.prep(),ledgers.saved());initialFence(r,ledgers,document,0);gate.arm(1);r.activate();until([&]{return gate.seen(1);});auto accepted=snapshot(ledgers.preparation);CHECK(accepted.health.accepted==1&&accepted.health.completed==0);gate.release();until([&]{return r.resident()>1&&!r.preparing();});CHECK(!r.failed());CHECK(snapshot(ledgers.preparation).health==accepted.health); // No tick: the real result's save worker remains uninstalled.
  drain(r,ledgers,document,0,1,2);CHECK(r.resident()==1);++cases;std::cout<<"PASS real_uninstalled_result_stays_outstanding_until_main_quiescence_reconciliation\n"<<std::flush;
 }
 gate.clear();
 {
  auto root=data/"foreground-yields-prefetch";auto book=importBook(app,source,root);auto document=library::documentRoot(root,book.id);auto p=prepared(app,document,1);Ledgers ledgers;reader::Reader r(app,document,std::move(p),{},ledgers.prep(),ledgers.saved());initialFence(r,ledgers,document,1);gate.arm(2);r.activate();until([&]{return gate.seen(2);});CHECK(snapshot(ledgers.preparation).health.accepted==2&&!gate.seen(0));CHECK(r.navigateTo(2));gate.release();until([&]{return r.backgroundYields()==1&&!r.preparing();});CHECK(!gate.seen(0)&&r.resident()<=4&&snapshot(ledgers.preparation).health.completed==0);until([&]{bool changed=r.tick();CHECK(!r.failed()&&r.resident()<=4);return changed&&r.page()==2;});r.installed();r.activate();until([&]{r.tick();CHECK(!r.failed());return snapshot(ledgers.preparation).health.completed==2;});CHECK(!gate.seen(0));drain(r,ledgers,document,2,2,3);++cases;std::cout<<"PASS foreground_skips_queued_prefetch_before_helper_start_with_exact_main_thread_prefix_reconciliation\n"<<std::flush;
 }
 gate.clear();
 {
  auto root=data/"cancelled-prefetch";auto book=importBook(app,source,root);auto document=library::documentRoot(root,book.id);auto p=prepared(app,document,1);Ledgers ledgers;reader::Reader r(app,document,std::move(p),{},ledgers.prep(),ledgers.saved());initialFence(r,ledgers,document,1);gate.arm(2);r.activate();until([&]{return gate.seen(2);});auto accepted=snapshot(ledgers.preparation);CHECK(accepted.health.accepted==2&&accepted.health.completed==0&&accepted.health.backlog==2&&!gate.seen(0));drain(r,ledgers,document,1,2,2);CHECK(!gate.seen(0)&&r.resident()==1);for(int page:{0,2}){CHECK(!std::filesystem::exists(reader::pagePath(document,page)/"prepared.bin"));CHECK(!std::filesystem::exists(reader::pagePath(document,page)/"prepared.bin.tmp"));}++cases;std::cout<<"PASS active_fifo_blocked_helper_reaped_plus_queued_never_started_request_both_reconciled\n"<<std::flush;
 }
 gate.clear();
 {
  auto root=data/"queued-position-intent";auto book=importBook(app,source,root);auto document=library::documentRoot(root,book.id);auto p=prepared(app,document,0);Ledgers ledgers;reader::Reader r(app,document,std::move(p),{},ledgers.prep(),ledgers.saved());initialFence(r,ledgers,document,0);gate.arm(1);r.activate();until([&]{return gate.seen(1);});gate.release();until([&]{r.tick();CHECK(!r.failed());return snapshot(ledgers.preparation).health.completed==1;});CHECK(r.navigateTo(1));CHECK(r.tick()&&r.page()==1&&snapshot(ledgers.resume).health.accepted==2);r.installed();r.activate();CHECK(snapshot(ledgers.preparation).health.accepted==2);drain(r,ledgers,document,1,2,3);++cases;std::cout<<"PASS actual_navigation_position_intent_and_final_durable_fence_retire_once_without_timing_inference\n"<<std::flush;
 }
 gate.clear();
 {
  auto root=data/"uninstalled-foreground";auto book=importBook(app,source,root);auto document=library::documentRoot(root,book.id);auto p=prepared(app,document,0);Ledgers ledgers;reader::Reader r(app,document,std::move(p),{},ledgers.prep(),ledgers.saved());initialFence(r,ledgers,document,0);gate.arm(1);r.activate();until([&]{return gate.seen(1);});CHECK(r.navigateTo(1));gate.release();until([&]{bool changed=r.tick();CHECK(!r.failed());return changed;});CHECK(r.page()==1&&r.state()==reader::State::Ready);drain(r,ledgers,document,0,1,3);++cases;std::cout<<"PASS prepared_but_unsubmitted_foreground_page_does_not_replace_final_displayed_resume\n"<<std::flush;
 }
 gate.clear();
 {
  auto root=data/"final-resume-failure";auto book=importBook(app,source,root);auto document=library::documentRoot(root,book.id);auto p=prepared(app,document,0);Ledgers ledgers;reader::Reader r(app,document,std::move(p),{},ledgers.prep(),ledgers.saved());initialFence(r,ledgers,document,0);auto resume=document/"resume.json",original=document/"resume-before-failure.json";auto initial=underlay::readBounded(resume,4096);CHECK(!std::filesystem::exists(original));std::filesystem::rename(resume,original);CHECK(std::filesystem::create_directory(resume));r.beginQuiesce();until([&]{return r.pollQuiesce(true,true);});CHECK(r.drained()&&r.failed()&&!r.shutdownSaved());auto failed=ledgers.resume.snapshot();CHECK(failed.fault==progress::Fault::WorkFailed&&failed.health.accepted==2&&failed.health.completed==1&&failed.health.backlog==1);CHECK(snapshot(ledgers.preparation).health.accepted==0&&std::filesystem::is_empty(resume)&&underlay::readBounded(original,4096)==initial);CHECK(std::filesystem::remove(resume));std::filesystem::rename(original,resume);for(unsigned n=0;n<24;++n){CHECK(r.pollQuiesce(true,true)&&!r.shutdownSaved());auto again=ledgers.resume.snapshot();CHECK(again.fault==failed.fault&&again.health==failed.health&&underlay::readBounded(resume,4096)==initial&&!reader::readViewResume(document,3,{}).clean);}++cases;std::cout<<"PASS actual_final_resume_failure_keeps_prefix_hole_and_sticky_unclean_fence\n"<<std::flush;
 }
 CHECK(owned.remove());std::cout<<"READER_PROGRESS_ROUTE_PASS cases="<<cases<<" actual_shell_reader=true private_fifo_wrapper=true real_prepare_helpers=true helper_main_reconciliation=true uninstalled_prefetch=true cancelled_queued_and_active=true resume_durable_prefix=true final_failure_not_completed=true repeated_poll_no_extra_jobs=true fake_tokens=NONE vendor_calls=0 provider_calls=NONE helpers_foreground_mapping=NOT_FULLY_QUALIFIED physical=NOT_RUN\n";return 0;
 }catch(const std::exception& e){std::cerr<<"READER_PROGRESS_ROUTE_FAIL "<<e.what()<<'\n';return 1;}}
